#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-16

# Test: agent frontmatter must not carry keys Claude Code ignores for PLUGIN agents.
#
# CC reads only a fixed key set for agents shipped inside a plugin. The ignored
# array was read out of the 2.1.226 binary and is identical on 2.1.227/2.1.231:
#
#     ["permissionMode", "hooks", "mcpServers"]
#     "Plugin agent file ${e} sets ${V}, which is ignored for plugin agents.
#      Use .claude/agents/ for this level of control."
#
# Two separate rules, because they have different strengths:
#
#   1. `hooks:` must be ABSENT everywhere. It has no consumer at all (the real
#      wiring is the dispatcher), so any occurrence is dead weight. #3494
#      deleted all 33; this test stops them coming back.
#
#   2. `mcpServers:` may still be declared with real content, because ork's own
#      tests/skills/test-mcp-pinning-check.sh reads it. But an EMPTY declaration
#      (`mcpServers: []`) expresses no intent while still paying the per-load
#      warning, so it is always wrong regardless of that pending decision. (#3461)
#
# This test deliberately does NOT ban a non-empty `mcpServers:`. That is an open
# product decision, and a test is the wrong place to force it.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
AGENTS_DIR="$REPO_ROOT/src/agents"

FAILED=0
CHECKED=0

echo "=== Agent Inert Frontmatter Test ==="
echo ""

if [ ! -d "$AGENTS_DIR" ]; then
    echo "FAIL: agents dir not found: $AGENTS_DIR"
    exit 1
fi

# Rule 1: `hooks:` must not appear in any agent's frontmatter.
echo "--- Rule 1: no 'hooks:' key (CC ignores it for plugin agents) ---"
HOOKS_HITS=0
while IFS= read -r file; do
    CHECKED=$((CHECKED + 1))
    if awk '/^---$/{n++; next} n==1 && /^hooks:/{found=1} END{exit !found}' "$file"; then
        echo "  FAIL: $(basename "$file") declares 'hooks:'"
        HOOKS_HITS=$((HOOKS_HITS + 1))
        FAILED=1
    fi
done < <(find "$AGENTS_DIR" -maxdepth 1 -name '*.md' -type f | sort)
[ "$HOOKS_HITS" -eq 0 ] && echo "  PASS: 0 agents declare 'hooks:'"
echo ""

# Rule 2: `mcpServers:` must not be declared empty.
echo "--- Rule 2: no empty 'mcpServers: []' (warning with no intent) ---"
EMPTY_HITS=0
while IFS= read -r file; do
    if awk '/^---$/{n++; next} n==1 && /^mcpServers:[[:space:]]*\[\][[:space:]]*$/{found=1} END{exit !found}' "$file"; then
        echo "  FAIL: $(basename "$file") declares an empty 'mcpServers: []'"
        EMPTY_HITS=$((EMPTY_HITS + 1))
        FAILED=1
    fi
done < <(find "$AGENTS_DIR" -maxdepth 1 -name '*.md' -type f | sort)
[ "$EMPTY_HITS" -eq 0 ] && echo "  PASS: 0 agents declare an empty 'mcpServers:'"
echo ""

echo "=== Summary ==="
echo "  agents checked          : $CHECKED"
echo "  'hooks:' declarations   : $HOOKS_HITS (must be 0)"
echo "  empty 'mcpServers: []'  : $EMPTY_HITS (must be 0)"
echo ""

if [ "$FAILED" -ne 0 ]; then
    echo "RESULT: FAIL"
    echo ""
    echo "Delete the offending key from the agent's frontmatter in src/agents/,"
    echo "then run 'npm run build' so plugins/ is regenerated in the same commit."
    exit 1
fi

echo "RESULT: PASS"
exit 0
